template <bool B>
inline bool VerifyComponentPayload(::flatbuffers::VerifierTemplate<B> &verifier, const void *obj, ComponentPayload type) {
  switch (type) {
    case ComponentPayload_NONE: {
      return true;
    }
    case ComponentPayload_TransformComponentData: {
      auto ptr = reinterpret_cast<const scene::TransformComponentData *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ComponentPayload_RectTransformComponentData: {
      auto ptr = reinterpret_cast<const scene::RectTransformComponentData *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ComponentPayload_CanvasComponentData: {
      auto ptr = reinterpret_cast<const scene::CanvasComponentData *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ComponentPayload_CameraComponentData: {
      auto ptr = reinterpret_cast<const scene::CameraComponentData *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ComponentPayload_FreeCameraComponentData: {
      auto ptr = reinterpret_cast<const scene::FreeCameraComponentData *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ComponentPayload_FbxRenderComponentData: {
      auto ptr = reinterpret_cast<const scene::FbxRenderComponentData *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ComponentPayload_RigidbodyComponentData: {
      auto ptr = reinterpret_cast<const scene::RigidbodyComponentData *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ComponentPayload_ColliderComponentData: {
      auto ptr = reinterpret_cast<const scene::ColliderComponentData *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ComponentPayload_PostEffectComponentData: {
      auto ptr = reinterpret_cast<const scene::PostEffectComponentData *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ComponentPayload_SkyboxComponentData: {
      auto ptr = reinterpret_cast<const scene::SkyboxComponentData *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ComponentPayload_GpuEffectComponentData: {
      auto ptr = reinterpret_cast<const scene::GpuEffectComponentData *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ComponentPayload_AnimationComponentData: {
      auto ptr = reinterpret_cast<const scene::AnimationComponentData *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ComponentPayload_NavAgentComponentData: {
      auto ptr = reinterpret_cast<const scene::NavAgentComponentData *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ComponentPayload_BehaviorTreeComponentData: {
      auto ptr = reinterpret_cast<const scene::BehaviorTreeComponentData *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ComponentPayload_UITextComponentData: {
      auto ptr = reinterpret_cast<const scene::UITextComponentData *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ComponentPayload_UIButtonComponentData: {
      auto ptr = reinterpret_cast<const scene::UIButtonComponentData *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ComponentPayload_UIImageComponentData: {
      auto ptr = reinterpret_cast<const scene::UIImageComponentData *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ComponentPayload_CpuParticleComponentData: {
      auto ptr = reinterpret_cast<const scene::CpuParticleComponentData *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ComponentPayload_UIPanelComponentData: {
      auto ptr = reinterpret_cast<const scene::UIPanelComponentData *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

template <bool B>
inline bool VerifyComponentPayloadVector(::flatbuffers::VerifierTemplate<B> &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<uint8_t> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyComponentPayload(
        verifier,  values->Get(i), types->GetEnum<ComponentPayload>(i))) {
      return false;
    }
  }
  return true;
}

